 "Supports software switch scanning via standard HID keyboard interfaces (Space for scan, Enter for select). All boards, symbols, and local storage operate 100% offline. Offline TTS relies strictly on locally installed OS speech synthesis voices.": "Prend en charge le balayage par contacteur logiciel via les interfaces clavier HID standard (Espace pour balayer, Entrée pour sélectionner). Tous les tableaux, symboles et le stockage local fonctionnent à 100 % hors ligne. La synthèse vocale hors ligne repose uniquement sur les voix installées sur le système d'exploitation.",
