 "This browser does not support camera/microphone access.": "Ce navigateur ne prend pas en charge l'accès à la caméra et au microphone.",
 "This feature is fully optional. Photos of your people are stored on this device only, not on our servers. When you ask \"who is this?\", photos are sent to the AI service for a one-time comparison. You can erase everything anytime with one button. Every person you save must agree.": "Cette fonction est entièrement facultative. Les photos de vos proches sont stockées uniquement sur cet appareil, pas sur nos serveurs. Quand vous demandez « qui est-ce ? », les photos sont envoyées au service d'IA pour une comparaison ponctuelle. Vous pouvez tout effacer à tout moment d'un seul bouton. Chaque personne que vous enregistrez doit être d'accord.",
 "This is an aid only — not a replacement for a white cane or guide dog. It cannot see everything.": "Ceci est une aide uniquement : elle ne remplace pas une canne blanche ou un chien guide. Elle ne peut pas tout voir.",
 "This message contains emergency alerts or modified text. Please confirm the exact wording before voicing aloud:": "Ce message contient des alertes d'urgence ou un texte modifié. Veuillez confirmer le texte exact avant de le dire à voix haute :",
 "This message contains emergency or sensitive terms. Please confirm before sending:": "Ce message contient des termes d'urgence ou sensibles. Veuillez confirmer avant d'envoyer :",
 "This section checks your room lighting and noise level on the spot using your camera and microphone, then suggests settings that are easier on your eyes and ears. Nothing is recorded or uploaded - the check runs only on your device and stops as soon as it finishes.": "Cette section vérifie sur place la lumière de votre pièce et le niveau de bruit avec votre caméra et votre microphone, puis propose des réglages plus doux pour vos yeux et vos oreilles. Rien n'est enregistré ni envoyé : la vérification s'exécute uniquement sur votre appareil et s'arrête dès qu'elle est terminée.",
