 "Yes, Clear All": "Oui, tout effacer",
 "You are an obstacle warner for a blind pedestrian. Look at the image: is there a close hazard in the walking path (hole, stairs, vehicle, pole, barrier, very close people, rope, sudden drop)? If yes: reply with ONE very short sentence starting with \"Warning\" naming the hazard and its direction (left/right/ahead). If the path is safe reply with exactly one word: safe.": "You are an obstacle warner for a blind pedestrian. Look at the image: is there a close hazard in the walking path (hole, stairs, vehicle, pole, barrier, very close people, rope, sudden drop)? If yes: reply with ONE very short sentence starting with \"Warning\" naming the hazard and its direction (left/right/ahead). If the path is safe reply with exactly one word: safe.",
