 "Strict Privacy Principle: Personal Assistant Memory is strictly opt-in and requires your explicit consent. All saved memory entries are encrypted locally on your device. Rafiqi only remembers authorized topics and accessibility preferences, and strictly forbids storing National IDs, bank cards, or passwords.": "Principe strict de confidentialité : la mémoire de l'assistant personnel est strictement facultative et exige votre consentement explicite. Toutes les entrées enregistrées sont chiffrées localement sur votre appareil. Rafiqi ne retient que les sujets autorisés et les préférences d'accessibilité, et interdit strictement de stocker des pièces d'identité, des cartes bancaires ou des mots de passe.",
